import 'package:flutter/material.dart';
import '../../data/models/models.dart';

/// Parcours complémentaire de 6e : cours et exercices sur les trois trimestres.
class SixiemeCompletionScreen extends StatelessWidget {
 const SixiemeCompletionScreen({super.key});
 static const _units=<_Unit>[
    _Unit('T1 • Français','Lire un récit et construire une phrase','Un récit présente un cadre (où et quand), des personnages et des actions organisées. Pour comprendre un texte, je repère la situation initiale, le problème, les actions et la fin. Une phrase verbale contient un verbe conjugué ; une phrase simple peut être organisée autour du sujet et du verbe. Je pose la question « qui est-ce qui ? » pour trouver le sujet, puis « que fait-il ? » pour repérer le verbe. Je distingue phrase déclarative, interrogative, exclamative et impérative. Je respecte la majuscule et le signe final.','« Le matin, Afi traverse le marché avec sa sœur. » Sujet : Afi ; verbe : traverse.','Quel est le verbe conjugué ?',['matin','traverse','sœur'],1,'Traverse est le verbe conjugué.'),
    _Unit('T1 • Mathématiques','Nombres entiers, décimaux et calcul','Je lis les nombres entiers et décimaux en identifiant unités, dizaines, centaines et chiffres après la virgule. Pour comparer, je regarde d’abord la partie entière puis les chiffres décimaux rang par rang. Pour additionner ou soustraire, j’aligne les virgules et je complète si nécessaire avec des zéros. Pour multiplier ou diviser, je pose les opérations proprement et vérifie par estimation ou opération inverse. Dans un problème, je relève les données, la question et l’unité attendue.','12,5 + 3,75 = 16,25.','Combien font 8,4 − 2,15 ?',['6,25','6,35','7,25'],0,'8,40 − 2,15 = 6,25.'),
    _Unit('T1 • Anglais','Greetings, classroom and personal information','Je sais saluer selon le moment : Good morning, Good afternoon, Hello et Goodbye. Pour me présenter, j’utilise My name is…, I am … years old et I live in…. Je demande le nom avec What is your name? et l’âge avec How old are you? Je distingue I, you, he, she, we et they. Je prononce clairement les mots, écoute mon interlocuteur et réponds par une phrase complète.','What is your name? — My name is Ama.','Comment demander l’âge ?',['Where are you?','How old are you?','What colour is it?'],1,'How old are you? signifie quel âge as-tu ?'),
    _Unit('T1 • SVT','Êtres vivants et milieux de vie','Un être vivant naît, grandit, se nourrit, respire, se reproduit puis meurt. Il vit dans un milieu dont il dépend pour trouver eau, nourriture, air, lumière ou abri. Pour comparer deux organismes, j’observe leur forme, leur déplacement, leur alimentation et leur milieu. Les plantes vertes ont besoin d’eau, de lumière et de dioxyde de carbone pour fabriquer leur matière. Je distingue les êtres vivants des objets non vivants et je respecte les habitats.','Une plante verte fabrique sa matière grâce à la lumière, à l’eau et au dioxyde de carbone.','Quel élément est nécessaire à la photosynthèse ?',['La lumière','Le plastique','Le sable sec uniquement'],0,'La lumière fournit l’énergie nécessaire à la photosynthèse.'),
    _Unit('T1 • Physique-Technologie','Matière et mesures','La matière est ce qui constitue les objets ; elle possède une masse et occupe un volume. La masse se mesure avec une balance et s’exprime notamment en grammes ou kilogrammes. Le volume se mesure avec un récipient gradué et s’exprime en litres, millilitres ou unités cubiques. Je lis le zéro et les graduations à hauteur des yeux. Je note toujours le nombre accompagné de son unité et je manipule le matériel avec soin.','Un litre correspond à 1 000 millilitres.','Quel instrument mesure la masse ?',['Une balance','Un thermomètre','Une règle'],0,'La balance sert à mesurer la masse.'),
    _Unit('T1 • Histoire-Géographie-EMC','Se repérer dans le temps et l’espace','Pour situer les événements, je lis une frise chronologique de gauche à droite et distingue passé, présent et futur. Une carte représente un espace ; son titre annonce le sujet, sa légende explique les symboles et son orientation indique les directions. Je sais repérer nord, sud, est et ouest. En éducation morale et civique, une règle protège les personnes et permet à chacun de jouir de ses droits tout en respectant ses devoirs.','Sur une frise, les dates sont placées dans l’ordre chronologique.','Quel outil ordonne les événements dans le temps ?',['Une frise chronologique','Un plan de table','Un thermomètre'],0,'La frise chronologique situe les événements dans le temps.'),
    _Unit('T2 • Français','Classes grammaticales et accords','Je reconnais le nom, le déterminant, l’adjectif qualificatif, le pronom, le verbe, l’adverbe et la préposition. Le déterminant accompagne le nom. L’adjectif précise le nom et s’accorde en genre et en nombre avec lui. Le verbe s’accorde avec son sujet : je cherche le sujet avant de conjuguer. Je distingue le singulier et le pluriel, le masculin et le féminin, puis je vérifie les accords dans tout le groupe nominal.','« Ces petites maisons blanches sont jolies. » Maisons est féminin pluriel.','Quelle forme est correctement accordée ?',['Les enfant joue','Les enfants jouent','Les enfants joue'],1,'Le sujet pluriel exige jouent.'),
    _Unit('T2 • Mathématiques','Fractions, proportionnalité et géométrie','Une fraction a un numérateur et un dénominateur : le dénominateur indique le nombre de parts égales et le numérateur le nombre de parts prises. Pour calculer une fraction d’une quantité, je divise par le dénominateur puis multiplie par le numérateur. Un tableau de proportionnalité permet de passer d’une grandeur à l’autre avec le même coefficient. En géométrie, des droites parallèles ne se coupent pas ; des droites perpendiculaires forment un angle droit. J’utilise règle et équerre.','3/4 de 20 = 15 ; si 1 cahier coûte 200 F, 3 cahiers coûtent 600 F.','Les 2/3 de 18 valent combien ?',['6','12','15'],1,'18 ÷ 3 × 2 = 12.'),
    _Unit('T2 • Anglais','Present simple, routines and questions','Le present simple décrit les habitudes, les vérités générales et les routines. À la forme affirmative, on ajoute généralement -s au verbe avec he, she et it : She reads. Pour poser une question, on utilise do avec I, you, we, they et does avec he, she, it. Après does, le verbe reste à sa base : Does he play? Pour nier, on utilise do not ou does not. Je sais décrire ma journée avec always, usually, sometimes et never.','She goes to school every day. Do you read?','Complète : He … football on Sundays.',['play','plays','playing'],1,'Avec he, on écrit plays.'),
    _Unit('T2 • SVT','Nutrition et digestion','Les aliments apportent de l’énergie et des matières nécessaires à la croissance. Une alimentation équilibrée est variée et adaptée à l’âge et à l’activité. La digestion commence dans la bouche : les dents broient les aliments et la salive les humidifie. Les aliments progressent dans le tube digestif et sont transformés en nutriments qui passent dans le sang au niveau de l’intestin grêle. Je respecte les règles d’hygiène, me lave les mains et bois de l’eau potable.','Les dents coupent et broient les aliments avant leur passage dans le tube digestif.','Où commence la digestion ?',['Dans la bouche','Dans le cœur','Dans les poumons'],0,'La digestion commence dans la bouche.'),
    _Unit('T2 • Physique-Technologie','Mélanges et changements d’état','Un corps pur contient une seule substance ; un mélange en contient plusieurs. Un mélange homogène paraît uniforme, tandis qu’un mélange hétérogène laisse distinguer plusieurs constituants. On peut séparer certains mélanges par décantation, filtration ou évaporation. La fusion fait passer un solide à l’état liquide ; la solidification fait passer un liquide à l’état solide ; la vaporisation conduit à l’état gazeux. La température et les conditions influencent ces changements.','La glace fond : elle passe de l’état solide à l’état liquide.','La vaporisation transforme un liquide en…',['solide','gaz','métal'],1,'La vaporisation fait passer à l’état gazeux.'),
    _Unit('T2 • Histoire-Géographie-EMC','Milieux, paysages et activités humaines','Un paysage rural comporte des champs, villages et espaces agricoles ; un paysage urbain présente souvent des immeubles, routes, commerces et services. Les habitants exercent des activités agricoles, artisanales, industrielles ou commerciales. Les activités humaines transforment le milieu et utilisent des ressources. Je compare les paysages en décrivant les éléments visibles, les activités et les voies de communication. Je propose des gestes pour préserver les espaces communs.','Un paysage urbain comporte souvent des bâtiments, des routes et des services.','Quelle activité est typiquement agricole ?',['Cultiver du maïs','Construire un pont','Conduire un autobus'],0,'Cultiver est une activité agricole.'),
    _Unit('T3 • Français','Conjugaison et production écrite','Le présent exprime une action actuelle ou habituelle ; le passé situe une action déjà réalisée et le futur annonce une action à venir. Pour rédiger un paragraphe, je choisis un sujet, formule une idée principale, ajoute des détails et organise les phrases avec des connecteurs : d’abord, ensuite, puis, enfin. Je relis pour corriger accords, conjugaison, ponctuation et répétitions. Je donne un titre adapté et je respecte la consigne.','D’abord, nous préparons le matériel. Ensuite, nous réalisons l’expérience.','Quel connecteur indique la suite ?',['Ensuite','Jamais','Pourtant'],0,'Ensuite marque la progression des actions.'),
    _Unit('T3 • Mathématiques','Périmètres, aires et résolution de problèmes','Le périmètre est la longueur du contour d’une figure ; l’aire mesure la surface occupée. Pour un rectangle, P = 2 × (longueur + largeur) et A = longueur × largeur. Pour un carré, P = 4 × côté et A = côté × côté. Je distingue cm, m, cm² et m². Avant de calculer, je convertis les mesures dans la même unité. Je dessine la figure, inscris les dimensions et vérifie si le résultat est cohérent.','Rectangle 9 cm × 4 cm : aire 36 cm² ; périmètre 26 cm.','Quelle est l’aire d’un rectangle de 7 cm sur 5 cm ?',['12 cm²','24 cm²','35 cm²'],2,'A = 7 × 5 = 35 cm².'),
    _Unit('T3 • Anglais','Past simple and everyday activities','The past simple parle d’une action terminée dans le passé. Les verbes réguliers prennent généralement -ed : play devient played. Plusieurs verbes sont irréguliers : go devient went, see devient saw. Pour poser une question, j’utilise did suivi de la base verbale ; pour nier, did not ou didn’t + base verbale. Les expressions yesterday, last week et two days ago indiquent souvent le passé. Je raconte trois actions dans l’ordre.','Yesterday, I played football. She went to school.','Quel est le prétérit de « see » ?',['seed','saw','seeing'],1,'See est irrégulier : son prétérit est saw.'),
    _Unit('T3 • SVT','Respiration, reproduction et environnement','La respiration permet à l’organisme d’utiliser le dioxygène et de rejeter le dioxyde de carbone. Chez l’être humain, l’air entre par les voies respiratoires et les échanges gazeux ont lieu au niveau des poumons. La reproduction permet aux espèces de se maintenir ; elle peut être sexuée ou asexuée selon les organismes. La biodiversité désigne la diversité des êtres vivants et des milieux. La pollution, la destruction des habitats et les feux menacent cette diversité.','Les poumons permettent les échanges entre l’air et le sang chez l’être humain.','Quel gaz l’organisme utilise-t-il pour la respiration ?',['Dioxygène','Hélium','Méthane'],0,'Le dioxygène est utilisé par les cellules.'),
    _Unit('T3 • Physique-Technologie','Électricité simple et sécurité','Un circuit électrique simple comprend un générateur (pile), des fils conducteurs et un récepteur (lampe). Le courant circule seulement si le circuit forme une boucle fermée. Un interrupteur ouvre ou ferme le circuit. Un schéma électrique utilise des symboles normalisés et des traits pour les fils. Je ne branche jamais un montage scolaire sur une prise domestique, ne touche pas un fil dénudé et demande l’aide de l’enseignant.','Une pile, des fils et une lampe forment un circuit simple si les connexions sont correctes.','Quand la lampe s’allume-t-elle ?',['Quand le circuit est fermé','Quand le fil est coupé','Sans générateur'],0,'Un circuit fermé alimenté permet le passage du courant.'),
    _Unit('T3 • Histoire-Géographie-EMC','Citoyenneté, environnement et bilan annuel','Être citoyen, c’est connaître ses droits, respecter ses devoirs, les lois et les personnes. À l’école, je respecte les règles, écoute les autres et prends soin du matériel commun. La protection de l’environnement demande de réduire les déchets, trier, économiser l’eau, protéger les arbres et ne pas polluer les cours d’eau. Pour préparer la classe suivante, je révise chaque matière, refais les exercices difficiles et explique mes démarches. Je révise et justifie mes réponses.','Trier les déchets et économiser l’eau sont des gestes responsables.','Quel geste protège l’environnement ?',['Jeter les déchets dans la rivière','Économiser l’eau et trier les déchets','Brûler les plastiques'],1,'Ces gestes limitent la pollution et le gaspillage.'),
 ];
 static int get unitCount=>_units.length;
 static int get lessonCount=>_units.length;
 static List<Exercise> assessmentExercisesForTerm(int term,{String? subjectName}){final prefix='T$term •';final result=<Exercise>[];for(var i=0;i<_units.length;i++){final u=_units[i];if(!u.title.startsWith(prefix))continue;if(subjectName!=null&&!_matches(u.title,subjectName))continue;result.add(Exercise(id:'six_t${term}_u${i}',lessonId:'six_t${term}_u${i}',question:u.question,options:u.options,correctIndex:u.answer,explanation:u.explanation));}return result;}
 static bool _matches(String title,String subject){final t=title.toLowerCase(),s=subject.toLowerCase();if(s.contains('français')||s.contains('francais'))return t.contains('français');if(s.contains('math'))return t.contains('mathématiques');if(s.contains('anglais')||s.contains('english'))return t.contains('anglais');if(s.contains('svt')||s.contains('science'))return t.contains('svt');if(s.contains('physique')||s.contains('technologie'))return t.contains('physique-technologie');if(s.contains('histoire')||s.contains('géographie')||s.contains('education')||s.contains('éducation')||s.contains('emc'))return t.contains('histoire-géographie-emc');return false;}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Complément 6ème • Année complète')),body:ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Text('${SixiemeCompletionScreen.unitCount} unités • ${SixiemeCompletionScreen.lessonCount} leçons • 3 trimestres\nLis le cours, étudie l’exemple, réponds puis consulte la correction.',style:const TextStyle(fontWeight:FontWeight.w600)))),for(final u in _units)_UnitTile(unit:u)]));
}
class _Unit{final String title,objective,content,example,question;final List<String> options;final int answer;final String explanation;const _Unit(this.title,this.objective,this.content,this.example,this.question,this.options,this.answer,this.explanation);}
class _UnitTile extends StatefulWidget{final _Unit unit;const _UnitTile({required this.unit});@override State<_UnitTile> createState()=>_UnitTileState();}
class _UnitTileState extends State<_UnitTile>{int? choice;bool checked=false;@override Widget build(BuildContext context){final u=widget.unit;return Card(margin:const EdgeInsets.only(bottom:10),child:ExpansionTile(title:Text(u.title,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text(u.objective),children:[Padding(padding:const EdgeInsets.fromLTRB(16,0,16,16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(u.content),const SizedBox(height:8),Text('Exemple : ${u.example}',style:const TextStyle(fontStyle:FontStyle.italic)),const SizedBox(height:12),Text(u.question,style:const TextStyle(fontWeight:FontWeight.bold)),for(var i=0;i<u.options.length;i++)RadioListTile<int>(dense:true,contentPadding:EdgeInsets.zero,value:i,groupValue:choice,title:Text(u.options[i]),onChanged:checked?null:(v)=>setState(()=>choice=v)),FilledButton.tonal(onPressed:choice==null?null:()=>setState(()=>checked=true),child:const Text('Vérifier ma réponse')),if(checked)Text('${choice==u.answer?'Bonne réponse ! ':'À revoir. Bonne réponse : ${u.options[u.answer]}. '}${u.explanation}',style:TextStyle(fontWeight:FontWeight.w600,color:choice==u.answer?Colors.green.shade800:Theme.of(context).colorScheme.error)),if(checked)TextButton(onPressed:()=>setState((){choice=null;checked=false;}),child:const Text('Recommencer'))]))]));}}
